-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "Melee DPS"
L["rm.era.warrior.dps.Description"] = "Levels 1–60, Arms and Fury, and every warrior outside Defensive Stance, also on Hardcore and Self-Found realms; built from simulator, Icy Veins and Wowhead. Charge to pull, Intercept a distant target, Whirlwind (Thunder Clap before you learn it) on three or more enemies fighting you, then Execute first below 20%, Sunder Armor to five on bosses without Expose Armor, Bloodthirst, Mortal Strike, Slam right after a swing with Improved Slam (set for a two-hander; change it in a clone), Whirlwind while keeping rage for your main strike, Overpower, Rend until your main strike is learned, Sunder Armor on healthy targets and Hamstring near the rage cap. Reminders: Battle Shout, Heroic Strike from 40 rage (20 while leveling), Cleave on packs, Bloodrage, Sweeping Strikes, Death Wish (bosses: their last 30 seconds), Recklessness with Death Wish, Pummel or Shield Bash. Intimidating Shout and Retaliation are listed off for Hardcore emergencies; stance dancing stays with you."
L["rm.era.warrior.protection.Name"] = "Tank"
L["rm.era.warrior.protection.Description"] = "Chosen whenever you are in Defensive Stance (Protection, Fury-Prot or a two-hander tank); built from Icy Veins and MaxDps. On four or more enemies: Demoralizing Shout and Battle Shout for threat. Then Revenge, Shield Slam, Bloodthirst, Sunder Armor to five, Demoralizing Shout on elites, Sunder Armor as the filler, and Rend before Shield Slam or Bloodthirst. Shield Slam and Shield Block only with a shield on. Reminders: Battle Shout, Shield Block while the target hits you, Bloodrage, Heroic Strike and Cleave from 50 rage, Shield Bash, Last Stand. Taunt, Shield Wall and Death Wish are listed off; Battle Stance for Execute (the DPS premade takes over) and Challenging Shout stay with you."
L["rm.era.warrior.protection.icyveins.Name"] = "Tank, Battle Shout threat (Icy Veins)"
L["rm.era.warrior.protection.icyveins.Description"] = "Icy Veins' \"sunderless\" tanking for groups where four or more players hear your shout (Phase 5 Battle Shout onward), an alternative to the recommended tank premade, off by default: enable it and disable that one, or raise its priority. Demoralizing Shout kept up, Revenge, Shield Slam or Bloodthirst, then Battle Shout as the threat filler instead of Sunder Armor; Shield Slam and Shield Block only with a shield on. Same reminders as the recommended tank; go back to Sunder when focusing one target in a crowd."
L["rm.forever.warrior.dps.Name"] = "Arms and Fury (Icy Veins)"
L["rm.forever.warrior.dps.Description"] = "Melee Arms and Fury from level 1 to 60, and the default for any warrior outside Defensive Stance. Forever rage is scarce and hidden from addons, so it pools by spending on anything else only while Mortal Strike or Bloodthirst is recovering: Charge to pull, Victory Rush, Intercept, Execute (in its range) on elites, bosses or in a group, Whirlwind or Thunder Clap, Demoralizing Shout and Slam on packs, Spearing Strike on Giants and Dragonkin, Rend until Bloodthirst, Overpower, Mortal Strike, Bloodthirst, then Whirlwind, Slam while standing and two Sunder Armors (five on elites). Reminders: Battle Shout, Bloodrage, the interrupt, Heroic Strike while the main strike recovers, Cleave on packs, Sweeping Strikes, Death Wish and Berserker Rage; Recklessness and Retaliation are listed but off. Left to you: stance dancing, Hamstring and consumables."
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "Arms and Fury, spend rage (Warcraft Tavern)"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "Warcraft Tavern's always-spend list for groups and raids: five Sunder Armors first, Execute above everything below 20%, Overpower, Rend until Bloodthirst, Mortal Strike, Bloodthirst, Whirlwind, Spearing Strike on cooldown, Slam once Improved Slam is taken; Heroic Strike or Cleave whenever you can afford them (rage is hidden on Forever, so there is no 60-rage threshold or spare-rage Hamstring), Recklessness on cooldown with Death Wish beside it. Choose it instead of the Icy Veins premade if you play in groups and do not need to save rage between pulls. An alternative to the recommended melee DPS premade, off by default: enable it and disable that one, or raise its priority."
L["rm.forever.warrior.protection.Name"] = "Protection (Icy Veins)"
L["rm.forever.warrior.protection.Description"] = "Tanking whenever you are in Defensive Stance, from level 10 to 60. Charges to pull (in Defensive Stance once you have Vanguard), Victory Rush, and on two or more enemies Thunder Clap on cooldown, Demoralizing Shout, Shield Slam, Revenge and Rend. On one target: Shield Slam, Revenge, Demoralizing Shout, Rend, Sunder Armor (five on elites) and Thunder Clap on dangerous targets. Reminders: Battle Shout, Bloodrage, Shield Bash, Shield Block while you hold the target, Heroic Strike while Shield Slam and Revenge are both recovering, Cleave on packs; Taunt and Shield Wall are listed but off. Rage, health and the target's mana are hidden from addons on Forever, so the rage thresholds, casters and Last Stand are your call. Left to you: swapping to Battle Stance to Charge before Vanguard, taunting other enemies and picking up loose ones."
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "Protection, debuff upkeep (Warcraft Tavern)"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "Warcraft Tavern's tanking order: Thunder Clap, Demoralizing Shout and five Sunder Armors kept on every target first, then Revenge, Rend and Shield Slam last, with Heroic Strike or Cleave whenever you can afford them (rage is hidden on Forever, so there is no 60-rage threshold). No Shield Block or defensive reminders. Choose it instead of the Icy Veins tank premade if you prefer to keep the debuffs up first. An alternative to the recommended Protection premade, off by default: enable it and disable that one, or raise its priority."
L["rm.mop.warrior.arms.Name"] = "Recommended"
L["rm.mop.warrior.arms.Description"] = "Recommended for Arms from level 10 to 90, picked in the Arms specialization. Charges to open, and again for rage when you step away. Colossus Smash whenever it is missing or about to end, Mortal Strike, Storm Bolt in the Smash window, Dragon Roar and Bladestorm outside it. Below 20% health: Execute in the window, at 100 rage or to keep Sudden Execute, Overpower on Taste for Blood. Otherwise Slam in the window, Overpower at four stacks, Slam at 100 rage, Overpower, Slam. Two or more enemies fighting you add Sweeping Strikes, Thunder Clap for Deep Wounds, Bladestorm and Dragon Roar. Victory Rush below 70% health; Battle Shout for rage. Reminders: a shout when none is up, Battle Stance, Berserker Rage, Recklessness, Avatar and Bloodbath with Colossus Smash on long fights, Skull Banner, Heroic Strike or Cleave with spare rage, Heroic Leap in the window, Pummel, Die by the Sword and Enraged Regeneration when low. Shattering Throw is listed but off. Left to you: canceling Bladestorm, stance dancing and positioning."
L["rm.mop.warrior.arms.icyveins.Name"] = "Pool for Colossus Smash (Icy Veins)"
L["rm.mop.warrior.arms.icyveins.Description"] = "Off by default. The Icy Veins and Wowhead Arms order: outside the Colossus Smash window it uses Overpower and Slams only above 80 rage, banking rage for the window instead of Slamming as filler. In the window: Mortal Strike, Slam, Overpower, Heroic Throw. Below 20% health: Colossus Smash, Mortal Strike, Execute, Overpower, Dragon Roar. Sweeping Strikes on two enemies, a Thunder Clap pack list on three or more. Heroic Strike or Cleave only near the rage cap. Same reminders as the recommended Arms premade. Enable it and disable that one to use it."
L["rm.mop.warrior.fury.Name"] = "Recommended"
L["rm.mop.warrior.fury.Description"] = "Recommended for Fury from level 10 to 90, picked in the Fury specialization. Charges to open and for rage. Colossus Smash once two Raging Blow charges are banked (one with Recklessness), Raging Blow as the window closes, Bloodthirst, Colossus Smash, Storm Bolt, Dragon Roar outside the window, Execute here with Single-Minded Fury (one-handers), Bladestorm while Bloodthirst cools, with Titan's Grip (two-handers) one more Raging Blow outside the window, Execute, Wild Strike on Bloodsurge, Raging Blow keeping a charge for the next window, Wild Strike, Heroic Throw, Battle Shout for rage. Two or more enemies fighting you add Bladestorm, Dragon Roar, Whirlwind for Meat Cleaver and cleaving Raging Blows. Reminders: a shout when none is up, Battle Stance, Berserker Rage for Enrage, Recklessness, Avatar and Bloodbath with Colossus Smash on long fights, Skull Banner, Heroic Strike or Cleave with spare rage, Heroic Leap, Pummel and defensives when low. Left to you: canceling Bladestorm."
L["rm.mop.warrior.fury.icyveins.Name"] = "Cooldowns in Colossus Smash (Icy Veins)"
L["rm.mop.warrior.fury.icyveins.Description"] = "Off by default. Icy Veins' Fury order spends Bladestorm or Dragon Roar first inside the Colossus Smash window, and puts Execute ahead of Bloodthirst below 20% health. Outside the window: Colossus Smash, Bloodthirst, Raging Blow only at two charges, Wild Strike on Bloodsurge, shout, Wild Strike. Four or more enemies: Bloodthirst for Enrage, Whirlwind to three Meat Cleaver stacks, Raging Blow. Heroic Strike or Cleave only near the rage cap. Same reminders as the recommended Fury premade. Enable it and disable that one to use it."
L["rm.mop.warrior.protection.Name"] = "Recommended"
L["rm.mop.warrior.protection.Description"] = "Tanking from level 10 to 90, picked in the Protection specialization. Charge or Heroic Throw to pull. Devastate to keep three Weakened Armor on elites and bosses, Dragon Roar, Bladestorm, Shockwave on three enemies and Thunder Clap on cooldown on three or more. Then Revenge for the last rage of a Shield Block, Shield Slam, Revenge on Hold the Line, Devastate for Deep Wounds, Victory Rush below 60% health, Revenge, Thunder Clap for Weakened Blows, Execute, Storm Bolt, a shout for rage and Devastate (Sunder Armor before 26). Reminders: Defensive Stance, a shout when none is up, Shield Block whenever it is down, Shield Barrier when hurt with rage to spare, Heroic Strike or Cleave on Ultimatum, Incite or near the cap, Demoralizing Shout, Berserker Rage, Enraged Regeneration, Last Stand and Shield Wall when low, your offensive cooldowns, Pummel. Taunt and Heroic Leap are listed but off. Left to you: whom to taunt, and Block versus Barrier against magic."
L["rm.mop.warrior.unspecialized.Name"] = "Unspecialized"
L["rm.mop.warrior.unspecialized.Description"] = "For levels 1 to 9, or until you choose a specialization. Charge to pull, Victory Rush, Execute and Heroic Strike when you have 30 rage; reminds you to be in Battle Stance if you are in no stance."
L["rm.retail.warrior.arms.Name"] = "Blizzard Assisted"
L["rm.retail.warrior.arms.Description"] = "Recommended for Arms in Midnight. In combat the game now hides rage, Rend, Colossus Smash, procs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat suggestion (the one-button rotation), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: Heroic Strike (a core button the suggestion never uses), Avatar and Champion's Spear in combat, Battle Shout between pulls, Pummel on an interruptible cast (it lights only where the game lets the cast be read), Die by the Sword whenever it is ready in combat (health is hidden on Retail, so when to use it is your call)."
L["rm.retail.warrior.arms.colossus.Name"] = "Colossus reference (SimulationCraft)"
L["rm.retail.warrior.arms.colossus.Description"] = "Reference only, off by default: the Colossus order from SimulationCraft and Icy Veins builds Colossal Might with Mortal Strike and reads buffs Midnight hides in combat. Charge to open; Sweeping Strikes on two or more; Mortal Strike below five Colossal Might; Rend before Colossus Smash; Ravager; Execute at two Sudden Death; Colossus Smash; Champion's Spear; Demolish in Colossus Smash with Colossal Might; Heroic Strike; Mortal Strike; Execute; Overpower; Rend under 5 seconds; Bladestorm on two or more; Slam. Reminders: Avatar, Die by the Sword, Battle Shout, Pummel."
L["rm.retail.warrior.arms.slayer.Name"] = "Slayer reference (SimulationCraft)"
L["rm.retail.warrior.arms.slayer.Description"] = "Reference only, off by default: the Slayer order from SimulationCraft, Icy Veins and Wowhead reads rage, Rend, Colossus Smash, Sudden Death and Opportunist, which Midnight hides in combat. Charge to open; Sweeping Strikes on two or more engaged enemies; Rend before Colossus Smash when it is running out; Ravager just before Colossus Smash; Execute at two Sudden Death; Colossus Smash; Bladestorm in Colossus Smash or Avatar; Heroic Strike; Overpower at two Opportunist; Mortal Strike; Execute; Overpower; Rend under 5 seconds; Slam. Reminders: Avatar with Colossus Smash ready, Die by the Sword, Battle Shout, Pummel."
L["rm.retail.warrior.fury.Name"] = "Blizzard Assisted"
L["rm.retail.warrior.fury.Description"] = "Recommended for Fury in Midnight. Shows Blizzard's Assisted Combat suggestion (Rampage, Bloodthirst, Raging Blow, Execute, Odyn's Fury and Bladestorm), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: Recklessness, Avatar and Champion's Spear in combat, Battle Shout between pulls, Pummel, Enraged Regeneration whenever it is ready in combat (health is hidden on Retail, so when to use it is your call)."
L["rm.retail.warrior.fury.slayer.Name"] = "Slayer reference (SimulationCraft)"
L["rm.retail.warrior.fury.slayer.Description"] = "Reference only, off by default: SimulationCraft's Slayer order reads Enrage, Recklessness and Sudden Death, which Midnight hides in combat; rage is hidden on Retail, so Rampage waits only for its cost. Charge to open; Whirlwind for its buff on two or more engaged enemies; Rampage when Enrage is ending; in Recklessness Rampage, Bladestorm, Execute on Sudden Death, Odyn's Fury; Crushing Blow; Bloodbath; Execute; Odyn's Fury; Raging Blow; Rampage; Bloodthirst; Whirlwind. Reminders: Recklessness, Avatar, Enraged Regeneration, Battle Shout, Pummel."
L["rm.retail.warrior.fury.thane.Name"] = "Mountain Thane reference (Icy Veins)"
L["rm.retail.warrior.fury.thane.Description"] = "Reference only, off by default: the Mountain Thane order from SimulationCraft and Icy Veins weaves Thunder Blast and reads buffs Midnight hides in combat. Charge to open; Whirlwind for its buff on two or more; Rampage when Enrage is missing or ending (rage is hidden on Retail, so there is no 100-rage Rampage); Bloodbath in Recklessness; Thunder Blast at two stacks; Crushing Blow; Bloodbath; Rampage in Recklessness; Thunder Blast in Avatar; Raging Blow; Thunder Blast; Rampage; Bloodthirst; Execute; Odyn's Fury; Thunder Clap; Whirlwind. Same reminders as the Slayer reference."
L["rm.retail.warrior.initial.Name"] = "Blizzard Assisted"
L["rm.retail.warrior.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Warrior's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Warrior premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.warrior.protection.Name"] = "Blizzard Assisted"
L["rm.retail.warrior.protection.Description"] = "Recommended for Protection in Midnight. Shows Blizzard's Assisted Combat suggestion for your damage and threat, and stops while you cast or have no enemy targeted. The suggestion never casts Shield Block or Ignore Pain, so both are reminders whenever they are usable and your target is attacking you; the game hides rage, so Ignore Pain will light more often than you need it. Other reminders: Avatar, Demoralizing Shout and Champion's Spear in combat, Shield Wall and Last Stand whenever they are ready in combat (health is hidden on Retail, so when to use them is your call), Taunt in a group when your target attacks someone else, Battle Shout between pulls, Pummel."
L["rm.retail.warrior.protection.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.warrior.protection.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order reads Shield Block, Thunder Blast and Colossal Might, which Midnight hides in combat; rage and health are hidden on Retail. Charge to open; Ravager; Thunder Blast at two stacks; Demolish at five Colossal Might; Shield Charge; Thunder Blast; Shield Slam; Thunder Clap; Execute; Revenge; Devastate. Reminders: Shield Block when its buff is down and you are tanking, Ignore Pain, Avatar, Demoralizing Shout, Champion's Spear, Shield Wall and Last Stand whenever they are ready in combat, Battle Shout, Pummel."
L["rm.sod.warrior.dps.Name"] = "Melee DPS (SoD)"
L["rm.sod.warrior.dps.Description"] = "Season of Discovery, levels 1–60 with runes as you engrave them: two-hander, dual wield, Gladiator and leveling, and every SoD warrior outside Defensive Stance; built from simulator Phase 6 and Wowhead Phase 7/8. Charge, Victory Rush, Intercept, Whirlwind (Thunder Clap before it) on two or more enemies, Slam at three Slammin' stacks, Rend kept up, Slam on Blood Surge (on cooldown with Precise Timing engraved), Bloodthirst, Mortal Strike, Shield Slam (with a shield), Overpower; then Quick Strike when it is engraved (two-hander), otherwise Whirlwind, Raging Blow and Devastate (Sunder before it); Execute with 30 rage or on Sudden Death; Hamstring near the rage cap. Reminders: Battle and Commanding Shout, Heroic Strike from 50 rage (always while Consumed by Rage enrages you), Cleave, Bloodrage, Rampage, Death Wish, Recklessness, Sweeping Strikes, interrupts. Berserker Rage and the Taste for Blood Battle Stance dip are listed off."
L["rm.sod.warrior.dps.icyveins.Name"] = "Melee DPS (SoD, Icy Veins)"
L["rm.sod.warrior.dps.icyveins.Description"] = "Icy Veins' Season of Discovery Fury and Arms pages, an alternative to the recommended Season of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its priority. Execute near the top below 20% or on Sudden Death, Slam on Blood Surge, Bloodthirst or Mortal Strike, Whirlwind, Overpower, Raging Blow, then Quick Strike and Hamstring only above 60 rage; no Rend; Heroic Strike only above 80 rage. Same reminders as the recommended premade."
L["rm.sod.warrior.dps.wowhead.Name"] = "Battle Forecaster stance dance (SoD, Wowhead)"
L["rm.sod.warrior.dps.wowhead.Description"] = "Wowhead's Phase 7/8 rotation for Soul of the Battle Forecaster or the Tier 1 six-piece (which Rotation Master cannot see), an alternative to the recommended Season of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its priority. Stance swaps to keep the forecast buffs up, Heroic Strike almost always, then Bloodthirst, Blood Surge Slam, Whirlwind, Raging Blow and Hamstring; no Rend and no Overpower. Check the swap timing in game before relying on it."
L["rm.sod.warrior.tank.Name"] = "Tank (SoD)"
L["rm.sod.warrior.tank.Description"] = "Season of Discovery tank, chosen in Defensive Stance; built from Wowhead Phase 8 and simulator. Charge; on two or more enemies Thunder Clap, Shockwave, Shield Slam, Revenge, Whirlwind and Devastate; then Shield Slam whenever Defender's Resolve is missing or ending, Revenge, Shield Slam, Shockwave, Execute, Whirlwind at five Gladiator's Cunning stacks, Devastate (Sunder before it), Demoralizing Shout and Thunder Clap on elites, Rend before Shield Slam; Shield Slam and Shield Block only with a shield on. Reminders: Battle and Commanding Shout, Shield Block, Heroic Strike from 50 rage, Cleave from 55, Bloodrage, Rampage, Last Stand, interrupts. Taunt, Shield Wall, Death Wish, Recklessness and Retaliation are listed off; the Gladiator swap for Execute stays with you."
L["rm.tbc.warrior.dps.icyveins.Name"] = "Melee DPS (Icy Veins)"
L["rm.tbc.warrior.dps.icyveins.Description"] = "Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and leveling steps as the simulator version, but with Mortal Strike Execute comes first, with Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you. An alternative to the recommended simulator melee DPS premade, off by default: enable it and disable that one, or raise its priority."
L["rm.tbc.warrior.dps.simulator.Name"] = "Melee DPS (simulator)"
L["rm.tbc.warrior.dps.simulator.Description"] = "Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept, Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare, Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts. Slam timing, stance dancing and Berserker Rage stay with you."
L["rm.tbc.warrior.protection.icyveins.Name"] = "Tank (Icy Veins)"
L["rm.tbc.warrior.protection.icyveins.Description"] = "Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins. Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield Block is reminded whenever your target is attacking you and you carry a shield. Taunting and other utility stay with you. An alternative to the recommended Wowhead tank premade, off by default: enable it and disable that one, or raise its priority."
L["rm.tbc.warrior.protection.wowhead.Name"] = "Tank (Wowhead)"
L["rm.tbc.warrior.protection.wowhead.Description"] = "Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge, Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block (with a shield equipped) against bosses and higher-level enemies, Heroic Strike or Cleave, Battle Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other utility stay with you."
